{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello हनोक जी आपको MRF motorcycle tyres की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "क्या है?"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "three piece चाहिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "चलिए अब vehicle brand के बारे में बात कर लेते हैं।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "आपको Hero, Bajaj या कुछ और चाहिए?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "नहीं Madam मैंने three wheeler है three wheeler तो चाहिए।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "समझ गए?"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "आपको three wheeler के लिए tyre चाहिए तो क्या आप मुझे अपनी गाड़ी का brand बता सकते हैं?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "पीआ जी।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "अब आप अपनी गाड़ी का..."
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "क्या आप अपनी गाड़ी का model या साल बता सकते हैं?"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "गाड़ी।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "Piaggio electric auto FX Max."
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "Okay madam।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "अभी जो है थोड़ा time लगेगा।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "Hello?"
    }
  ]
}
